import java.util.*;

class Solution {
    public int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode cur = root;
        while (true) {
            while (cur != null) { stack.push(cur); cur = cur.left; } // go as far left as possible
            cur = stack.pop();       // next smallest key
            if (--k == 0) return cur.val;
            cur = cur.right;
        }
    }
}

